**行号：Reply.ts L77–L114**

### 代码原文
```ts
// src7/plugins/channels/Reply.ts
  77  /** 事件 channel/reply 请求载荷。 */
  78  export interface ChannelReplyRequest {
  79    /** 单次事件往返局部关联 ID。 */
  80    requestId: string;
  81    /** 渠道名（feishu / wechat / http / cli）。 */
  82    channel: string;
  83    /** 当前机器人名。 */
  84    bot: string;
  85    /** 回复请求幂等键。 */
  86    replyRequestKey: string;
  87    /** 回复轮键。 */
  88    replyRoundKey: string;
  89    /** 本轮内序号。 */
  90    replyIndex: number;
  91    /** 回复类别：progress | final。 */
  92    kind: ReplyKind;
  93    /** 发送模式：纯文字或附件。 */
  94    mode: 'text' | 'attachment';
  95    /**
  96     * 不可变来源快照：回某条消息时有。
  97     * 没有的（旧路自动回话、relay 回信、本人批准的主动发件）一定带 target.address，照它发。
  98     */
  99    sourceSnapshot?: messageModule.SourceSnapshot;
 100    /** 请求正文摘要，用于同键冲突校验。 */
 101    payloadHash: string;
 102    /** 发送片段列表。 */
 103    parts: ReplyPartInput[];
 104    /** 跨渠道或跨聊天发送目标；未指定别处时为 undefined，沿用 sourceSnapshot。 */
 105    target?: targetModule.ChannelReplyTarget;
 106    /** 哪场会话说的：旧路自动回话、relay 回信带上，渠道照会话定细节（命令行出错标红，微信只发做完的一轮，网页挂回会话认领的那条）。 */
 107    sessionId?: string;
 108    /** 正文里的 @路径（存在的本机文件）当文件一起发：只有旧路自动回话、relay 回信开，模型的 channel_reply 不开；只有飞书认，别的渠道照纯文字发。 */
 109    atFiles?: boolean;
 110    /** 负责处理的渠道插件置 true，区分“无人监听该渠道”。 */
 111    handled?: boolean;
 112  }
 113
 114
```

### 解释
- L80：`requestId` 是一次事件往返的局部关联号；L86、L88、L90：幂等键、轮键、轮内序号。
- L94：发送模式；L99：回某条消息时带来源快照，没有的（旧路自动回话、relay 回信、本人批准的主动发件）一定带 `target.address`。
- L101：正文摘要，同键冲突校验用；L103：发送片段。
- L105：跨渠道、跨聊天的目标；L107：哪场会话说的；L109：正文里的 @路径 当文件发（只有飞书认）。
- L111：负责的渠道插件置 true，用来区分“没人监听这个渠道”。

### 谁用它
