 193  export async function requestChannelReply(
 194    ctx: cordis.Context,
 195    req: Omit<ChannelReplyRequest, 'requestId'>,
 196    timeoutMs = 30_000,
 197  ): Promise<ReplyReceipt> {
 198    //M 没人接单能确认没发，超时或异常时无法确认投递。
 199    const onFallback = (cause: requestEvents.FallbackReason, detail?: string): ChannelRepliedEvent => {
 200      let status: ReplyStatus = 'uncertain';
 201      let reason = detail ?? '等待渠道发送回执超时';
 202      if (cause === 'unhandled') {
 203        status = 'rejected';
 204        reason = `channel_unavailable：渠道 ${req.channel} 没挂`;
 205      }
 206      const receipt = getReceipt(req, status, reason);
 207      const request = { ...req, requestId: '' };
 208      return { requestId: '', replyRoundKey: req.replyRoundKey, receipt, request };
 209    };
 210
 211    const options = { prefix: 'rep', timeoutMs, keepAlive: true, onFallback };
 212    //M 交给公共请求工具配对回执，只向上层交回渠道处理结果。
 213    const result = await requestEvents.requestEvent(ctx, 'channel/reply', 'channel/replied', req, options);
 214    return result.receipt;
 215  }
