  81    let label = exact;
  82    const labelPrefix = labelPrefixes.find((one) => exact.startsWith(one));
  83    if (labelPrefix !== undefined) {
  84      label = exact.slice(labelPrefix.length);
  85    }
  86
  87    //M “前缀:聊天”写法：冒号不在开头、两边去空白后都不空才算。
  88    const plain = { exact, label, prefix: '', chat: '' };
  89    const sep = exact.indexOf(':');
  90    if (sep <= 0) return plain;
  91
  92    const prefix = exact.slice(0, sep).trim();
  93    const chat = exact.slice(sep + 1).trim();
  94    if (prefix === '' || chat === '') return plain;
  95
  96    return { exact, label, prefix, chat };
  97  }
